import * as React from "react";

import {
    ACTION_CLOSE,
    ACTION_NEXT,
    ACTION_PREV,
    ACTION_SWIPE,
    ACTIVE_SLIDE_COMPLETE,
    ACTIVE_SLIDE_ERROR,
    ACTIVE_SLIDE_LOADING,
    ACTIVE_SLIDE_PLAYING,
} from "./consts.js";

/** Lightbox external props */
export type LightboxExternalProps = DeepPartial<
    DeepPartial<DeepPartial<LightboxProps, "animation" | "toolbar">, "carousel", "imageProps">,
    "controller",
    "ref"
>;

/** Lightbox properties */
export interface LightboxProps {
    /** if `true`, the lightbox is open */
    open: boolean;
    /** a callback to close the lightbox */
    close: Callback;
    /** starting slide index */
    index: number;
    /** slides to display in the lightbox */
    slides: Slide[];
    /** custom render functions */
    render: Render;
    /** custom UI labels */
    labels: Labels;
    /** enabled plugins */
    plugins: Plugin[];
    /** toolbar settings */
    toolbar: ToolbarSettings;
    /** carousel settings */
    carousel: CarouselSettings;
    /** animation settings */
    animation: AnimationSettings;
    /** controller settings */
    controller: ControllerSettings;
    /** portal settings */
    portal: PortalSettings;
    /** lifecycle callbacks */
    on: Callbacks;
    /** customization styles */
    styles: SlotStyles;
    /** CSS class of the lightbox root element */
    className: string;
}

/** Slide */
export type Slide = SlideTypes[SlideTypeKey];

/** Supported slide types */
export interface SlideTypes {
    /** image slide type */
    image: SlideImage;
}

/** Slide type key */
export type SlideTypeKey = keyof SlideTypes;

/** Generic slide */
export interface GenericSlide {
    type?: SlideTypeKey;
}

/** Image slide properties */
export interface SlideImage extends GenericSlide {
    /** image slide type */
    type?: "image";
    /** image URL */
    src: string;
    /** image 'alt' attribute */
    alt?: string;
    /** image width in pixels */
    width?: number;
    /** image height in pixels */
    height?: number;
    /** `object-fit` setting */
    imageFit?: ImageFit;
    /** alternative images to be passed to the 'srcSet' */
    srcSet?: ImageSource[];
}

/** Image source */
export interface ImageSource {
    /** image URL */
    src: string;
    /** image width in pixels */
    width: number;
    /** image height in pixels */
    height: number;
}

/** Image fit setting */
export type ImageFit = "contain" | "cover";

/** Lightbox component */
export type Component = React.ComponentType<ComponentProps>;

/** Lightbox component properties */
export type ComponentProps = React.PropsWithChildren<Omit<LightboxProps, "slides" | "index" | "plugins">>;

/** Lightbox component tree node */
export type Node = {
    /** module */
    module: Module;
    /** module child nodes */
    children?: Node[];
};

/** Lightbox module */
export type Module = {
    /** module name */
    name: string;
    /** module component */
    component: Component;
};

/** Lightbox props augmentation */
export type Augmentation = (props: ComponentProps) => ComponentProps;

/** Container rect */
export type ContainerRect = {
    width: number;
    height: number;
};

/** Customization slots */
export type Slot = SlotType[keyof SlotType];

/** Supported customization slots */
export interface SlotType {
    /** lightbox root customization slot */
    root: "root";
    /** lightbox container customization slot */
    container: "container";
    /** lightbox slide customization slot */
    slide: "slide";
    /** lightbox button customization slot */
    button: "button";
    /** lightbox icon customization slot */
    icon: "icon";
    /** lightbox toolbar customization slot */
    toolbar: "toolbar";
    /** lightbox Prev navigation button customization slot */
    navigationPrev: "navigationPrev";
    /** lightbox Next navigation button customization slot */
    navigationNext: "navigationNext";
}

/** Customization slot CSS properties */
interface SlotCSSProperties extends React.CSSProperties {
    [key: `--yarl__${string}`]: string | number;
}

/** Customization slots styles */
export type SlotStyles = {
    [key in Slot]?: SlotCSSProperties;
};

/** Carousel settings */
export interface CarouselSettings {
    /** if `true`, the lightbox carousel doesn't wrap around */
    finite: boolean;
    /** the lightbox preloads (2 * preload + 1) slides */
    preload: number;
    /** padding around each slide (e.g., "16px", "10%" or 0) */
    padding: LengthOrPercentage;
    /** spacing between slides (e.g., "100px", "50%" or 0) */
    spacing: LengthOrPercentage;
    /** `object-fit` setting for image slides */
    imageFit: ImageFit;
    /** custom image attributes */
    imageProps: Omit<
        React.ImgHTMLAttributes<HTMLImageElement>,
        "src" | "alt" | "sizes" | "srcSet" | "onLoad" | "onError" | "onClick"
    >;
}

export type LengthOrPercentage = `${number}px` | `${number}%` | number;

/** Animation settings */
export interface AnimationSettings {
    /** fade-in / fade-out animation settings */
    fade: number;
    /** swipe animation settings */
    swipe: number;
    /** override for `swipe` animation settings when using keyboard navigation or navigation buttons */
    navigation?: number;
    /** animation timing function settings */
    easing: {
        /** fade-in / fade-out animation timing function */
        fade: string;
        /** slide swipe animation timing function */
        swipe: string;
        /** slide navigation animation timing function (when using keyboard navigation or navigation buttons) */
        navigation: string;
    };
}

/** Controller settings */
export interface ControllerSettings {
    /** controller ref */
    ref: React.ForwardedRef<ControllerRef>;
    /** if true, the lightbox captures focus when it opens */
    focus: boolean;
    /** controller `touch-action` */
    touchAction: "none" | "pan-y";
    /** if `true`, set ARIA attributes on the controller div */
    aria: boolean;
    /** if `true`, close the lightbox on pull-down gesture */
    closeOnPullDown: boolean;
    /** if `true`, close the lightbox when the backdrop is clicked */
    closeOnBackdropClick: boolean;
}

/** Lightbox controller ref */
export interface ControllerRef {
    /** navigate to the previous slide */
    prev: Callback<NavigationAction | void>;
    /** navigate to the next slide */
    next: Callback<NavigationAction | void>;
    /** close the lightbox */
    close: Callback;
    /** transfer focus to the lightbox controller */
    focus: Callback;
    /** get lightbox props */
    getLightboxProps: () => ComponentProps;
    /** get lightbox state */
    getLightboxState: () => LightboxState;
}

/** Portal settings */
export interface PortalSettings {
    /** portal mount point */
    root?: DocumentFragment | Element | null;
}

/** Lightbox navigation action */
export interface NavigationAction {
    /** navigate through the specified number of slides */
    count?: number;
}

/** Lightbox state swipe action */
export type LightboxStateSwipeAction = {
    type: "swipe";
    increment: number;
    duration?: number;
    easing?: string;
};

/** Lightbox state update action */
export type LightboxStateUpdateAction = {
import { LightboxProps } from "./types.js";
import { ACTION_CLOSE, IMAGE_FIT_CONTAIN } from "./consts.js";

export const LightboxDefaultProps: LightboxProps = {
    open: false,
    close: () => {},
    index: 0,
    slides: [],
    render: {},
    plugins: [],
    toolbar: { buttons: [ACTION_CLOSE] },
    labels: {},
    animation: {
        fade: 250,
        swipe: 500,
        easing: {
            fade: "ease",
            swipe: "ease-out",
            navigation: "ease-in-out",
        },
    },
    carousel: {
        finite: false,
        preload: 2,
        padding: "16px",
        spacing: "30%",
        imageFit: IMAGE_FIT_CONTAIN,
        imageProps: {},
    },
    controller: {
        ref: null,
        focus: true,
        aria: false,
        touchAction: "none",
        closeOnPullDown: false,
        closeOnBackdropClick: false,
    },
    portal: {},
    on: {},
    styles: {},
    className: "",
};

import * as React from "react";

import {
    ACTION_NEXT,
    ACTION_PREV,
    ACTION_SWIPE,
    CLASS_FLEX_CENTER,
    cleanup,
    clsx,
    cssClass,
    cssVar,
    getSlide,
    hasSlides,
    Slide,
    useAnimation,
    useEventCallback,
    useEvents,
    useLightboxProps,
    useLightboxState,
    useRTL,
} from "../../index.js";
import { cssPrefix, cssThumbnailPrefix } from "./utils.js";
import { Thumbnail } from "./Thumbnail.js";
import { defaultThumbnailsProps, useThumbnailsProps } from "./props.js";

function isHorizontal(position: ReturnType<typeof useThumbnailsProps>["position"]) {
    return ["top", "bottom"].includes(position);
}

function boxSize(thumbnails: ReturnType<typeof useThumbnailsProps>, dimension: number, includeGap?: boolean) {
    return dimension + 2 * (thumbnails.border + thumbnails.padding) + (includeGap ? thumbnails.gap : 0);
}

export type ThumbnailsTrackProps = {
    visible: boolean;
    containerRef: React.RefObject<HTMLDivElement>;
};

export function ThumbnailsTrack({ visible, containerRef }: ThumbnailsTrackProps) {
    const track = React.useRef<HTMLDivElement | null>(null);

    const { carousel, styles } = useLightboxProps();
    const { slides, globalIndex, animation } = useLightboxState();
    const { publish, subscribe } = useEvents();
    const isRTL = useRTL();

    const thumbnails = useThumbnailsProps();
    const { position, width, height, border, borderRadius, padding, gap, vignette } = thumbnails;

    const index = globalIndex;
    const animationDuration = animation?.duration || 0;
    const offset = (animationDuration > 0 && animation?.increment) || 0;

    const { prepareAnimation } = useAnimation<number>(track, (snapshot) => ({
        keyframes: isHorizontal(position)
            ? [
                  {
                      transform: `translateX(${
                          (isRTL ? -1 : 1) * boxSize(thumbnails, width, true) * offset + snapshot
                      }px)`,
                  },
                  { transform: "translateX(0)" },
              ]
            : [
                  {
                      transform: `translateY(${boxSize(thumbnails, height, true) * offset + snapshot}px)`,
                  },
                  { transform: "translateY(0)" },
              ],
        duration: animationDuration,
        easing: animation?.easing,
    }));

    const handleControllerSwipe = useEventCallback(() => {
        let animationOffset = 0;
        if (containerRef.current && track.current) {
            const containerRect = containerRef.current.getBoundingClientRect();
            const trackRect = track.current.getBoundingClientRect();
            animationOffset = isHorizontal(position)
                ? trackRect.left - containerRect.left - (containerRect.width - trackRect.width) / 2
                : trackRect.top - containerRect.top - (containerRect.height - trackRect.height) / 2;
        }

        prepareAnimation(animationOffset);
    });

    React.useEffect(() => cleanup(subscribe(ACTION_SWIPE, handleControllerSwipe)), [subscribe, handleControllerSwipe]);

    const { finite } = carousel;
    const preload = Math.min(carousel.preload, Math.floor(slides.length / 2));

    const items: { slide: Slide | null; index: number; placeholder?: boolean }[] = [];

    if (hasSlides(slides)) {
        if (offset < 0) {
            for (let i = index - preload + offset; i < index - preload; i += 1) {
                items.push({ slide: null, index: i, placeholder: true });
            }
        }

        for (let i = index - preload - Math.max(offset, 0); i < index; i += 1) {
            if (!(finite && i < 0)) {
                items.push({ slide: getSlide(slides, i), index: i });
            } else {
                items.push({ slide: null, index: i, placeholder: true });
            }
        }

        items.push({ slide: getSlide(slides, index), index });

        for (let i = index + 1; i <= index + preload - Math.min(offset, 0); i += 1) {
            if (!finite || i <= slides.length - 1) {
                items.push({ slide: getSlide(slides, i), index: i });
            } else {
                items.push({ slide: null, index: i, placeholder: true });
            }
        }

        if (offset > 0) {
            for (let i = index + preload + 1; i <= index + preload + offset; i += 1) {
                items.push({ slide: null, index: i, placeholder: true });
            }
        }
    }

    const handleClick = (slideIndex: number) => () => {
        if (slideIndex > index) {
            publish(ACTION_NEXT, { count: slideIndex - index });
        } else if (slideIndex < index) {
            publish(ACTION_PREV, { count: index - slideIndex });
        }
    };

    return (
        <div
            className={clsx(cssClass(cssPrefix("container")), cssClass(CLASS_FLEX_CENTER))}
            style={{
                ...(!visible ? { display: "none" } : null),
                ...(width !== defaultThumbnailsProps.width
                    ? { [cssVar(cssThumbnailPrefix("width"))]: `${boxSize(thumbnails, width)}px` }
                    : null),
                ...(height !== defaultThumbnailsProps.height
                    ? { [cssVar(cssThumbnailPrefix("height"))]: `${boxSize(thumbnails, height)}px` }
                    : null),
                ...(border !== defaultThumbnailsProps.border
                    ? { [cssVar(cssThumbnailPrefix("border"))]: `${border}px` }
                    : null),
                ...(borderRadius !== defaultThumbnailsProps.borderRadius
                    ? { [cssVar(cssThumbnailPrefix("border_radius"))]: `${borderRadius}px` }
                    : null),
                ...(padding !== defaultThumbnailsProps.padding
                    ? { [cssVar(cssThumbnailPrefix("padding"))]: `${padding}px` }
                    : null),
                ...(gap !== defaultThumbnailsProps.gap ? { [cssVar(cssThumbnailPrefix("gap"))]: `${gap}px` } : null),
                ...styles.thumbnailsContainer,
            }}
        >
            <nav
                ref={track}
                style={styles.thumbnailsTrack}
                className={clsx(cssClass(cssPrefix("track")), cssClass(CLASS_FLEX_CENTER))}
            >
                {items.map(({ slide, index: slideIndex, placeholder }) => {
                    const fadeAnimationDuration = animationDuration / Math.abs(offset || 1);

                    const fadeIn =
                        (offset > 0 && slideIndex > index + preload - offset && slideIndex <= index + preload) ||
                        (offset < 0 && slideIndex < index - preload - offset && slideIndex >= index - preload)
                            ? {
                                  duration: fadeAnimationDuration,
                                  delay:
                                      ((offset > 0
                                          ? slideIndex - (index + preload - offset)
                                          : index - preload - offset - slideIndex) -
                                          1) *
                                      fadeAnimationDuration,
                              }
                            : undefined;

                    const fadeOut =
                        (offset > 0 && slideIndex < index - preload) || (offset < 0 && slideIndex > index + preload)
                            ? {
                                  duration: fadeAnimationDuration,
                                  delay:
                                      (offset > 0
                                          ? offset - (index - preload - slideIndex)
                                          : -offset - (slideIndex - (index + preload))) * fadeAnimationDuration,
                              }
                            : undefined;

                    return (
                        <Thumbnail
                            key={slideIndex}
                            slide={slide}
                            active={slideIndex === index}
                            fadeIn={fadeIn}
                            fadeOut={fadeOut}
                            placeholder={Boolean(placeholder)}
                            onClick={handleClick(slideIndex)}
                        />
                    );
                })}
            </nav>
            {vignette && <div className={cssClass(cssPrefix("vignette"))} />}
        </div>
    );
}

import { composePrefix, PLUGIN_THUMBNAILS } from "../../index.js";

export const cssPrefix = (value?: string) => composePrefix(PLUGIN_THUMBNAILS, value);

export const cssThumbnailPrefix = (value?: string) => cssPrefix(composePrefix("thumbnail", value));
import * as React from "react";
import { act, render, screen } from "@testing-library/react";

import { clickButton, expectCurrentImageToBe, expectToContainButton, lightbox } from "../utils.js";
import { Fullscreen, Thumbnails, Video } from "../../../src/plugins/index.js";
import { LightboxExternalProps } from "../../../src/index.js";

function renderLightbox(props?: LightboxExternalProps) {
    return render(
        lightbox({
            slides: [{ src: "image1" }, { src: "image2" }, { src: "image3" }],
            plugins: [Thumbnails],
            ...props,
        })
    );
}

function queryThumbnails() {
    return screen
        .queryAllByRole("button")
        .filter((el) => el.className.split(" ").includes("yarl__thumbnails_thumbnail"));
}

function clickThumbnail(image: string) {
    act(() => {
        queryThumbnails()
            .find((el) => Boolean(el.querySelector(`img[src='${image}']`)))!
            .click();
    });
}

function expectThumbnails(visible = true) {
    expect(queryThumbnails().length > 0).toBe(visible);
}

function expectNavigation() {
    clickButton("Next");
    clickButton("Previous");
    expectThumbnails();
}

describe("Thumbnails", () => {
    it("renders without crashing", () => {
        renderLightbox();
        expectNavigation();
    });

    it("supports thumbnails toggle button", () => {
        renderLightbox({ thumbnails: { showToggle: true } });
        expectThumbnails();

        clickButton("Hide thumbnails");
        expectThumbnails(false);

        clickButton("Show thumbnails");
        expectThumbnails();
    });

    it("supports thumbnails navigation", () => {
        renderLightbox({ carousel: { preload: 1 } });
        expectCurrentImageToBe("image1");

        clickThumbnail("image2");
        expectCurrentImageToBe("image2");

        clickThumbnail("image1");
        expectCurrentImageToBe("image1");
    });

    it("supports thumbnails position", () => {
        renderLightbox({ thumbnails: { position: "top" } });
        expectNavigation();

        renderLightbox({ thumbnails: { position: "bottom" } });
        expectNavigation();

        renderLightbox({ thumbnails: { position: "start" } });
        expectNavigation();

        renderLightbox({ thumbnails: { position: "end" } });
        expectNavigation();
    });

    it("works with Fullscreen", () => {
        // Fullscreen plugin must be listed first
        renderLightbox({ plugins: [Fullscreen, Thumbnails] });
        expectThumbnails();
    });

    it("supports custom thumbnails button", () => {
        renderLightbox({
            thumbnails: { showToggle: true },
            render: { buttonThumbnails: () => React.createElement("button", { type: "button" }, "Custom button") },
        });
        expectToContainButton("Custom button");
    });

    it("supports thumbnails customization", () => {
        renderLightbox({ thumbnails: { border: 2, borderRadius: 5, width: 60, height: 40, padding: 10, gap: 10 } });
        expectThumbnails();
    });

    it("supports finite carousel", () => {
        renderLightbox({ carousel: { finite: true } });
        expectThumbnails();

        clickButton("Next");
        expectThumbnails();
    });

    it("supports video thumbnails", () => {
        renderLightbox({
            slides: [{ type: "video", poster: "poster", sources: [{ src: "video", type: "video/mp4" }] }],
            plugins: [Thumbnails, Video],
        });
        clickThumbnail("poster");
    });

    it("supports unknown slide types", () => {
        // @ts-expect-error
        renderLightbox({ slides: [{ type: "custom" }] });
        expectThumbnails();
    });

    it("supports custom thumbnails", () => {
        renderLightbox({ render: { thumbnail: () => React.createElement("img", { src: "custom" }) } });
        clickThumbnail("custom");
    });
});

